import{_ as n,l as s,o as a,c as i,v as t,p as l,x as o,d as E,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"支付系统与 RTGS","description":"","frontmatter":{"title":"支付系统与 RTGS","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/rtgs-payments.md","filePath":"econ/rtgs-payments.md","lastUpdated":1789023840000}'),m={name:"econ/rtgs-payments.md"};function A(S,e,B,c,h,T){const r=s("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="支付系统与-rtgs" tabindex="-1">支付系统与 RTGS <a class="header-anchor" href="#支付系统与-rtgs" aria-label="Permalink to &quot;支付系统与 RTGS&quot;">​</a></h1><div class="epigraph"><p>大额支付的最终性，取决于用哪一种结算资产、在哪一个时点解除暴露。</p><footer>—— 据 BIS Committee on Payment and Settlement Systems, Real-Time Gross Settlement Systems, 1997；Core Principles for Systemically Important Payment Systems, 2001 整理</footer></div><p>定位：<a href="/econ/reserve-endogenous-money">上一课</a>。贷款创造存款之后，存款转账仍要在银行之间过户一笔结算资产。本课缺口是这笔过户的协议：准备金作为支付结算资产，实时全额（RTGS）与延迟净额（DNS）如何改变日内暴露。不重写「贷款同时创造存款」，不把支付系统写成挤兑博弈。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内生货币已经说明：企业把存款从银行 A 付到银行 B，系统内广义货币不变，变的是准备金在 A 与 B 之间的分配。若结算日终才轧差，A 在日内对 B（或对清算所）持有未覆盖的信用暴露——这正是传染课里那种银行间债权，只是寿命以小时计。若每笔支付当时就用央行货币全额结算，暴露被压到结算间隔之内，但银行必须在日内持有或借入准备金。</p><p>缺口不是再讲乘数，而是：盯利率体制下准备金迁就的是<strong>结算需求</strong>，支付系统的规则决定需求以何种峰值出现。BIS 的大额支付报告把选择收成 RTGS 对 DNS。</p><p><span class="marginnote">最终性（finality）：支付不可撤销、不可被清盘人追回。RTGS 用央行货币逐笔达到最终性。DNS 的最终性推迟到轧差时点，此前是参与者之间的信用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>DNS：一日（或一周期）内支付对冲，净额用结算资产交割。节约准备金，制造未结算头寸。一家在轧差前倒闭，未完成的净额要unwind，对手突然出现流动性缺口——支付系统自己就是传染边。RTGS：每笔全额、实时、用央行准备金（或央行保证的账户）结算。信用暴露被设计掉，换成流动性管理： outgoing 支付要先有准备金或日内信贷。</p><p>央行通常配套日内透支或抵押信贷，使 RTGS 不至于因为准备金存量过小而锁死队列。盯利率时，这些日内便利按需提供，正是上一课「准备金迁就结算」的操作面。法定准备金率可以很低甚至为零，结算仍需要央行负债当轨道。</p>',10)),(a(),l(d,null,{default:o(()=>[p(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAY%5B%22%E8%B7%A8%E8%A1%8C%E6%94%AF%E4%BB%98%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20DNS%5B%22%E5%BB%B6%E8%BF%9F%E5%87%80%E9%A2%9D%3A%20%E8%8A%82%E7%BA%A6%E5%87%86%E5%A4%87%E9%87%91%2C%20%E7%95%99%E4%BF%A1%E7%94%A8%E6%9A%B4%E9%9C%B2%22%5D%0A%20%20PAY%20--%3E%20RTGS%5B%22%E5%AE%9E%E6%97%B6%E5%85%A8%E9%A2%9D%3A%20%E5%A4%AE%E8%A1%8C%E8%B4%A7%E5%B8%81%E9%80%90%E7%AC%94%E6%9C%80%E7%BB%88%22%5D%0A%20%20RTGS%20--%3E%20INTRA%5B%22%E6%97%A5%E5%86%85%E4%BF%A1%E8%B4%B7%E6%88%96%E9%98%9F%E5%88%97%22%5D%0A%20%20DNS%20--%3E%20X%5B%22%E8%BD%A7%E5%B7%AE%E5%89%8D%E5%80%92%E9%97%AD%3A%20unwind%22%5D%0A%20%20INTRA%20--%3E%20RES%5B%22%E5%87%86%E5%A4%87%E9%87%91%E6%98%AF%E7%BB%93%E7%AE%97%E8%B5%84%E4%BA%A7%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与<a href="/econ/money-as-medium">货币层次</a>的衔接：公众的 \\(M1\\) 是银行存款；银行之间不拿存款结清，拿准备金。层次图上的 \\(H\\) 在这里不是乘数的种子，是轨道上的车。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是结算资产的排他性。只有被所有参与者按面值接受、且其发行人不在参与者之中的负债，才能在倒闭时仍当最终货币。这就是央行准备金。商业银行存款是 inside money，对公众是支付手段，对银行同业不是最终结算。RTGS 把这一区分写成时刻表：每一笔大额，当时就换成 outside money。</p><p>队列与流动性节约算法（排队、对冲、部分净额）是在 RTGS 内部再省准备金，不回到「日终才最终」。省的是峰值，不是最终性定义。若把这些算法写成「其实还是 DNS」，会把暴露重新藏进队列规则。</p><h3 id="准备金约束在日内-不在乘数" tabindex="-1">准备金约束在日内，不在乘数 <a class="header-anchor" href="#准备金约束在日内-不在乘数" aria-label="Permalink to &quot;准备金约束在日内，不在乘数&quot;">​</a></h3><p>上一课的因果箭头是：盯利率则 \\(H\\) 迁就 \\(D\\)。本课补上频率：迁就发生在支付高峰，而不是在月度货币统计里。走廊或地板利率决定日内信贷的价格；抵押与限额决定谁能把结算需求变成央行资产。没有这条，内生货币会听起来像银行可以在真空里转账。</p><p><span class="marginnote">证券结算的 DVP（券款对付）把「钱」与「券」的最终性绑在同一时点，避免光脚的本金风险。逻辑与 RTGS 同构，对象换成券。本课不展开 CSD 的法律结构。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 RTGS 叫成货币政策工具：它是结算规则，利率规则才是工具。也不要把支付系统写成<a href="/econ/lender-of-last-resort">最后贷款人</a>——窗口是恐慌时对 outside money 的弹性；RTGS 是平时每一笔用哪种资产达到最终。恐慌中支付系统停摆，两者才叠在同一张表上。</p><p>本课不写 LCR 的流出假设，不写影子银行的批发结算。后课 Bagehot 处理挤兑时谁必须提供 \\(H\\)；本课只钉：\\(H\\) 首先是结算资产。</p><p>后课默认：跨行支付用准备金最终；RTGS 用流动性换掉 DNS 的信用暴露。内生货币的「迁就」是迁就这条轨道，不是否认结算需要央行负债。</p><p>法定准备金率接近零，不取消结算对 \\(H\\) 的需求。需求的形状由支付规则决定。</p><p>不要用「贷款创造存款」跳过同业过户。创造发生在单家账上；最终发生在央行账上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>准备金是银行间支付的结算资产，不是贷款的事前原料。</li><li>DNS 省准备金、留日内信用；RTGS 逐笔最终、把问题改成日内流动性。</li><li>盯利率时央行按需提供结算用 \\(H\\)，与内生货币兼容。</li><li>出处：BIS CPSS, <em>RTGS Systems</em> 1997；<em>Core Principles</em> 2001。</li></ul>',15))])}const D=n(m,[["render",A]]);export{u as __pageData,D as default};
